  mi_review:function(){ return card('mi_review','<div class="row" style="margin-bottom:7px;"><div class="mark">M</div><div class="lbl">Milton flag for coach</div></div><div style="font-size:12.5px;line-height:1.5;color:var(--gray);">Bench marked too easy twice. Consider adding a set or +5 lb.</div>','dash'); },

  /* next actions */
