  na_primary:function(){ return wrap('na_primary','<button class="btn primary" style="margin-bottom:9px;"><svg width="16" height="16" viewBox="0 0 18 18" fill="none"><path d="M3 4.5h12a1.5 1.5 0 011.5 1.5v6A1.5 1.5 0 0115 13.5H8l-3.5 3v-3H3A1.5 1.5 0 011.5 12V6A1.5 1.5 0 013 4.5z" stroke="#f5f7f6" stroke-width="1.4" stroke-linejoin="round"/></svg> Text Milton</button>'); },
