  na_reminder:function(){ return card('na_reminder','<div class="sub" style="margin:0;text-align:center;">Milton will check in by text tomorrow morning.</div>'); },

  /* education */
  ed_tip:function(){ return card('ed_tip','<div class="lbl" style="color:#2b7a78;">Quick tip</div><div style="font-size:13px;line-height:1.5;margin-top:5px;color:#173a2f;">Protein at breakfast makes the rest of the day easier.</div>','tint'); },
