  ed_video:function(){ return card('ed_video','<div class="row"><div class="ph" style="width:48px;height:38px;border-radius:8px;"><div class="blur pc"></div></div><div><div class="h-strong" style="font-size:13px;">Protein basics</div><div class="sub" style="margin-top:2px;">Coach · 3 min</div></div></div>'); },
  ed_demo:function(){ return card('ed_demo','<div class="row"><div class="ph" style="width:40px;height:40px;border-radius:9px;"><div class="blur pa"></div></div><div><div class="h-strong" style="font-size:13px;">Squat form</div><div class="sub" style="margin-top:2px;">Cue: knees track over toes</div></div></div>'); },

  /* challenge / program */
  cp_progress:function(){ return card('cp_progress','<div class="barrow"><span class="h-strong">Week 3 of 4</span><span class="lbl">75%</span></div><div class="bar"><i style="width:75%"></i></div>'); },
  cp_score:function(){ return card('cp_score','<div class="barrow"><span class="lbl">Challenge score</span><span class="val" style="font-size:23px;">312</span></div><div class="sub">Meals · Workouts · Photos · Check-ins</div>'); },
  cp_leaderboard:function(){ return card('cp_leaderboard','<div class="row"><div class="val" style="font-size:22px;color:#2b7a78;">#4</div><div class="h-strong" style="font-size:13px;">in workout consistency this week</div></div>'); },
  cp_badge:function(){ return card('cp_badge','<div style="display:flex;gap:9px;justify-content:center;"><div style="text-align:center;"><div style="width:44px;height:44px;border-radius:50%;background:rgba(92,219,149,.3);display:flex;align-items:center;justify-content:center;font-size:19px;">🔥</div><div class="lbl" style="margin-top:5px;">Protein Streak</div></div><div style="text-align:center;"><div style="width:44px;height:44px;border-radius:50%;background:rgba(58,175,169,.18);display:flex;align-items:center;justify-content:center;font-size:19px;">✅</div><div class="lbl" style="margin-top:5px;">First 10</div></div></div>'); },
  cp_summary:function(){ return card('cp_summary','<div class="lbl" style="color:#5cdb95;">30 days complete</div><div style="font-size:13px;line-height:1.6;margin-top:7px;">Logged <b>72 meals</b>, completed <b>14 workouts</b>, lost <b>6.8 lb</b>.</div>','dark'); },

  /* business / retention */
  br_checkin:function(){ return card('br_checkin','<button class="btn ghost">Book your monthly check-in</button>'); },
  br_upgrade:function(){ return card('br_upgrade','<div style="font-size:13px;line-height:1.5;">Upgrade to weekly nutrition review for deeper feedback.</div><button class="btn ghost" style="margin-top:9px;">Learn more</button>'); },
  br_renewal:function(){ return card('br_renewal','<div class="sub" style="margin:0;">Your program ends in <b style="color:var(--navy)">10 days</b>.</div>','amber'); },
