  mkBlk(exName, sets, reps, weight, cat, src){
    const ex=this.exercises.find(e=>e.name===exName);
    const supports = ex? {...ex.metric} : {sets:true,reps:true,weight:true,duration:false,distance:false,calories:false};
    const values={sets:'',reps:'',weight:'',duration:'',distance:'',calories:'',rest:90};
    if(supports.sets) values.sets=sets; if(supports.reps) values.reps=reps;
    if(supports.weight) values.weight=weight; if(supports.duration&&!supports.weight) values.duration=reps;
    return { id:'blk_'+Math.random().toString(36).slice(2,8), exId:ex?ex.id:null, name:exName, cat:cat||'strength', supports, values, notes:'', source:src||'agent_programmed', collapsed:true };
  }
  // build progressed weekly content from per-day exercise themes
  seedContent(themes, weeks, readyWeeks){
    const content={};
    Object.keys(themes).forEach(dow=>{
      themes[dow].forEach((t,exIdx)=>{}); // noop
    });
    for(let w=0; w<weeks; w++){
      Object.keys(themes).forEach(dow=>{
        const key='w'+w+'_'+dow;
        if(w>=readyWeeks){ content[key]=[]; return; } // empty future weeks coach extends
        content[key]=themes[dow].map(t=>{
          const baseW=t[3]; const prog=baseW? Math.round(baseW*(1+0.05*w)) : '';
          return this.mkBlk(t[0], t[1], t[2], prog, t[4], 'agent_programmed');
        });
      });
    }
    return content;
  }

  // day-count -> weekday set, used to seed the mockup-derived program library
  DOWSET={ 2:['TUE','THU'], 3:['MON','WED','FRI'], 4:['MON','TUE','THU','FRI'], 5:['MON','TUE','WED','THU','FRI'] };
  genContent(dows, weeks, ready){
    const pool=[
      ['Barbell Full Squat',4,8,85,'strength'],
      ['Romanian Deadlift',3,10,60,'accessory'],
      ['Barbell Bench Press',4,8,60,'strength'],
      ['Seated Cable Row',3,10,55,'accessory'],
      ['Box Jump',4,8,'','conditioning'],
      ['Bird Dog',3,10,'','core'],
    ];
    const theme={};
    dows.forEach((dow,i)=>{ theme[dow]=[ pool[i%pool.length], pool[(i+2)%pool.length], pool[(i+4)%pool.length] ]; });
    return this.seedContent(theme, weeks, ready);
  }
  // build a full program record from a compact mockup-style spec
  mkProgram(s){
    const dows=this.DOWSET[s.days]||['MON','WED','FRI'];
    const bounded = s.state!=='archived';
    const ready = s.state==='draft' ? Math.max(1, Math.round(s.weeks*(s.pct||0)/100)) : s.weeks;
    const type = s.type||'group';
    return {
      id:s.id, tenant:this.TENANT, name:s.name, type,
      clientName: type==='private' ? (s.client||'Assigned client') : '',
      daysOfWeek:dows, startTime:s.startTime||'9:00 AM', duration:s.duration||60,
      bounded, weeks:s.weeks, readyWeeks:ready, capacity: type==='private'?1:(s.clients||12),
      enrollmentMode: type==='group'?'self_enroll':'assigned',
      coachId: s.coach||'You', guidance:s.guidance||'', focus:s.focus||'',
      status:s.state, programmingStatus: s.state==='draft'?'partial':'ready',
      assigned: s.clients||0, updated:s.touched||s.finished||'Jun 2026',
      // library display fields (from mockup)
      coachName:(s.coach||null), clients:s.clients||0,
      adherence:s.adherence||null, week:s.week||null, endsSoon:!!s.ends_soon, nextAssigned:!!s.next_assigned,
      from:s.from||null, pct:s.pct||null, touched:s.touched||null, stalled:!!s.stalled,
      used:s.used||0, finished:s.finished||null,
      content:this.genContent(dows, s.weeks, ready),
    };
  }

