            <button sc-camel-on-click="{{ sendActive }}" style="padding:10px 20px; border-radius:999px; background:var(--teal-800); color:var(--white); border:0; font-family:inherit; font-size:14px; font-weight:600; cursor:pointer; box-shadow:var(--shadow-sm);" style-hover="background:var(--teal-700);">{{ activeSendLabel }}</button>
